		case RESOURCE_FORMAT_R16_SNORM:
		case RESOURCE_FORMAT_R16_UINT:
		case RESOURCE_FORMAT_R16_SINT:
		case RESOURCE_FORMAT_R16_SFLOAT:
		case RESOURCE_FORMAT_D16_UNORM:
