}
void gf2128mul(gf2128 *c, gf2128 *a, gf2128 *b){
  gf2128 V;
  gf2128 Z;
  gf2128 temp;
  gf2128zero(&V);
  gf2128zero(&Z);
  gf2128zero(&temp);
  gf2128add(&V, &V, b);
  for(int i=0; i<128; i++){
    if(a->c[i]){
      assert(a->c[i]<2);
      gf2128add(&Z,&Z,&V);
    }
    gf2128mulx(&temp,&V);
    gf2128mov(&V, &temp);
  }
  gf2128mov(c, &Z);
}
