#include <stdarg.h>
#include "print.h"

int	my_put_nbr_base16maj(va_list va)
{
  int		divide;
  unsigned int	digit;
  unsigned int	nb;
  char		*base;

  base = "0123456789ABCDEF";
  nb = va_arg(va, unsigned int);
  divide = 1;
  while (nb / divide >= 16)
    divide = divide * 16;
  while (divide > 0)
    {
      digit = (nb / divide) % 16;
      my_putchar(base[digit]);
      divide = divide / 16;
    }
  return (0);
}

