void function_header(char *name, int vars, int has_call, int num_pars) {
	int a;

	variables = vars+(has_call ? num_pars : 0);
	printf("# setting call to %i\n", has_call);
	call = has_call;

	printf("\t.globl %s\n\t.type %s, @function\n%s:\n", name, name, name);
