		trace_paraver_event (cpu, ptask, task, thread, current_time,
		  SAMPLING_ADDRESS_MEM_HITORMISS_EV, EvValue);
	}
	else if (Get_EvEvent (current) == SAMPLING_ADDRESS_TLB_LEVEL_EV)
	{
